namespace StudyConnect.Core.Entities;

/// <summary>
/// Base class for every persisted entity. Provides the surrogate primary key and a
/// creation timestamp so that each derived entity does not have to repeat them.
/// </summary>
public abstract class EntityBase
{
    /// <summary>Primary key (generated by the database).</summary>
    public int Id { get; set; }

    /// <summary>When the row was created, always stored in UTC.</summary>
    public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow;
}
